+/** UC-002: Browse veterinarians and their specialties with infinite scrolling. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+        Grid<Vet> grid = new Grid<>();
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : String.join(", ", vet.specialties()))
+                .setHeader("Specialties").setKey("specialties");
+        grid.setSizeFull();
+        grid.setItems(this::fetch, query -> count());
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(DataAccessException exception) {
+        LoggerFactory.getLogger(VetsView.class).error("Unable to load veterinarians", exception);
+        // Lazy callbacks also run after navigation, outside the router's error handling.
+        UI ui = UI.getCurrent();
+        ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                ui.getInternals().getActiveViewLocation(),
+                new IllegalStateException("Unable to load veterinarians. Please try again."),
+                NavigationTrigger.PROGRAMMATIC, null);
+    }
+}
